/* Entry bundle: core navigation, non-blocking boot telemetry, reveal, spotlight, lightbox, HUD clock, and lazy feature hydration */

import {
  reduceMotion,
  stillPlaying,
  motionChangeListeners,
  finePointer,
  hydrateMedia,
  preloaderDone,
  resolvePreloaderDone,
  registry,
  mascotGlance,
  decode,
  smoothScroller,
  navigateToHash,
  ensureForHash,
  refreshMaxScroll,
  getMaxScroll,
  AudioFX,
  Toast,
} from "./shared.js";

/* 1. Header & Drawer -------------------------------------------------- */
const header = document.querySelector("[data-header]");
if (header) {
  const brand = header.querySelector(".brand");
  const proofStrip = document.querySelector(".proof-strip");
  const collapsibles = Array.from(header.querySelectorAll("[data-header-collapsible]"));
  const menuToggle = document.querySelector("[data-menu-toggle]");
  const drawer = document.getElementById("site-drawer");
  const backdrop = document.querySelector("[data-menu-backdrop]");
  const drawerLinks = drawer ? Array.from(drawer.querySelectorAll("[data-drawer-link]")) : [];
  const drawerCloseTriggers = drawer ? Array.from(drawer.querySelectorAll("[data-drawer-close]")) : [];

  let splitEndY = 660;
  let isMenuOpen = false;
  let drawerInertTargets = [];
  let headerMetricsReady = false;
  let headerScrollRaf = 0;
  let menuAnimTimer = 0;
  let lastSplitKey = "";

  const clamp01 = (v) => (v <= 0 ? 0 : v >= 1 ? 1 : v);
  const smooth = (t) => t * t * (3 - 2 * t);

  const syncHeaderMetrics = () => {
    headerMetricsReady = true;
    if (brand) {
      let naturalLeft = 0;
      let node = brand;
      while (node && node !== header) {
        naturalLeft += node.offsetLeft;
        node = node.offsetParent;
      }
      const vw = window.innerWidth;
      const targetLeft = vw <= 560 ? 20 : Math.min(44, Math.max(20, Math.round(vw * 0.03)));
      const dx = Math.round(targetLeft - naturalLeft);
      header.style.setProperty("--header-brand-dx", `${dx}px`);
    }

    const headerH = Math.round(header.getBoundingClientRect().height) || 81;
    if (proofStrip) {
      const proofDocTop = proofStrip.getBoundingClientRect().top + window.scrollY;
      splitEndY = Math.min(760, Math.max(240, Math.round(proofDocTop - headerH - 24)));
    }
  };

  const syncCollapsedInert = () => {
    const collapsed = header.classList.contains("is-scrolled") || isMenuOpen;
    collapsibles.forEach((el) => {
      if (collapsed) {
        el.setAttribute("inert", "");
        el.setAttribute("aria-hidden", "true");
      } else {
        el.removeAttribute("inert");
        el.removeAttribute("aria-hidden");
      }
    });
  };

  const updateHeader = () => {
    const y = window.scrollY;
    if (y > 0 && !headerMetricsReady) syncHeaderMetrics();

    const rawP = clamp01(y / splitEndY);
    let splitP = 0;
    let splitBar = 0;
    let splitName = 0;
    let splitRight = 0;
    let splitMenu = 0;

    if (stillPlaying()) {
      const snapped = rawP >= 0.5 ? 1 : 0;
      splitP = snapped;
      splitBar = snapped;
      splitName = snapped;
      splitRight = snapped;
      splitMenu = snapped;
    } else if (rawP > 0) {
      splitP = smooth(rawP);
      splitBar = smooth(clamp01(rawP / 0.42));
      splitName = smooth(clamp01(rawP / 0.58));
      splitRight = smooth(clamp01(rawP / 0.65));
      splitMenu = smooth(clamp01((rawP - 0.52) / 0.48));
    }

    const key = `${splitP.toFixed(4)}|${splitBar.toFixed(4)}|${splitName.toFixed(4)}|${splitRight.toFixed(4)}|${splitMenu.toFixed(4)}`;
    if (key !== lastSplitKey) {
      lastSplitKey = key;
      header.style.setProperty("--split-p", splitP.toFixed(4));
      header.style.setProperty("--split-bar", splitBar.toFixed(4));
      header.style.setProperty("--split-name", splitName.toFixed(4));
      header.style.setProperty("--split-right", splitRight.toFixed(4));
      if (menuToggle) {
        menuToggle.style.setProperty("--split-menu", splitMenu.toFixed(4));
      }
    }

    const collapsed = rawP >= 0.65;
    const menuReady = rawP >= 0.62;
    header.classList.toggle("is-scrolled", collapsed);
    header.classList.toggle("is-menu-ready", menuReady);
    syncCollapsedInert();
  };

  const scheduleHeaderUpdate = () => {
    if (headerScrollRaf) return;
    headerScrollRaf = window.requestAnimationFrame(() => {
      headerScrollRaf = 0;
      updateHeader();
    });
  };

  const triggerMenuAnim = () => {
    if (stillPlaying()) return;
    if (menuAnimTimer) window.clearTimeout(menuAnimTimer);
    header.classList.add("is-menu-animating");
    menuAnimTimer = window.setTimeout(() => {
      header.classList.remove("is-menu-animating");
      menuAnimTimer = 0;
    }, 450);
  };

  const syncDrawerActiveSection = () => {
    if (!drawerLinks.length) return;
    const anchorY = Math.round(window.innerHeight * 0.34);
    let activeHref = "";
    if (window.scrollY > 120) {
      const candidates = [];
      for (const link of drawerLinks) {
        const href = link.getAttribute("href");
        if (!href || !href.startsWith("#")) continue;
        const sec = document.getElementById(href.slice(1));
        if (sec) candidates.push({ href, top: sec.getBoundingClientRect().top });
      }
      for (const item of candidates) {
        if (item.top <= anchorY) activeHref = item.href;
      }
    }
    drawerLinks.forEach((link) => {
      if (link.getAttribute("href") === activeHref) {
        link.setAttribute("aria-current", "location");
      } else {
        link.removeAttribute("aria-current");
      }
    });
  };

  const openDrawer = () => {
    if (!drawer || isMenuOpen) return;
    isMenuOpen = true;
    syncHeaderMetrics();
    syncDrawerActiveSection();
    triggerMenuAnim();
    header.classList.add("is-menu-open");
    drawer.classList.add("is-open");
    drawer.setAttribute("aria-hidden", "false");
    drawer.removeAttribute("inert");
    if (backdrop) backdrop.classList.add("is-open");
    if (menuToggle) {
      menuToggle.setAttribute("aria-expanded", "true");
      menuToggle.setAttribute("aria-label", "Close menu");
    }
    syncCollapsedInert();
    document.body.classList.add("dialog-open");

    drawerInertTargets = Array.from(
      document.querySelectorAll("main, footer.site-footer, aside.hud, .colophon-drawer")
    ).filter((el) => !el.hasAttribute("inert"));
    drawerInertTargets.forEach((el) => el.setAttribute("inert", ""));

    if (drawerLinks[0]) {
      window.requestAnimationFrame(() => {
        if (isMenuOpen) drawerLinks[0].focus({ preventScroll: true });
      });
    }
  };

  const closeDrawer = ({ restoreFocus = true } = {}) => {
    if (!drawer || !isMenuOpen) return;
    isMenuOpen = false;
    triggerMenuAnim();
    header.classList.remove("is-menu-open");
    drawer.classList.remove("is-open");
    drawer.setAttribute("aria-hidden", "true");
    drawer.setAttribute("inert", "");
    if (backdrop) backdrop.classList.remove("is-open");
    if (menuToggle) {
      menuToggle.setAttribute("aria-expanded", "false");
      menuToggle.setAttribute("aria-label", "Open menu");
    }
    drawerInertTargets.forEach((el) => el.removeAttribute("inert"));
    drawerInertTargets = [];
    document.body.classList.remove("dialog-open");
    syncCollapsedInert();

    if (restoreFocus && menuToggle && header.classList.contains("is-menu-ready")) {
      menuToggle.focus({ preventScroll: true });
    }
  };

  if (menuToggle && drawer) {
    menuToggle.addEventListener("click", () => {
      if (isMenuOpen) closeDrawer({ restoreFocus: true });
      else openDrawer();
    });
    if (backdrop) {
      backdrop.addEventListener("click", () => closeDrawer({ restoreFocus: true }));
    }
    drawerLinks.forEach((link) => {
      link.addEventListener("click", () => closeDrawer({ restoreFocus: false }));
    });
    drawerCloseTriggers.forEach((btn) => {
      btn.addEventListener("click", () => closeDrawer({ restoreFocus: false }), { capture: true });
    });
    if (brand) {
      brand.addEventListener("click", () => {
        if (isMenuOpen) closeDrawer({ restoreFocus: false });
      });
    }
    window.addEventListener("keydown", (event) => {
      if (!isMenuOpen) return;
      if (event.key === "Escape") {
        if (document.querySelector("dialog[open]")) return;
        event.preventDefault();
        closeDrawer({ restoreFocus: true });
      }
    });
  }

  let headerResizeRaf = 0;
  motionChangeListeners.push(updateHeader);
  if (window.scrollY > 0) updateHeader();
  window.addEventListener("pageshow", (event) => {
    if (event.persisted && window.scrollY > 0) updateHeader();
  }, { once: true });
  window.addEventListener("scroll", scheduleHeaderUpdate, { passive: true });
  window.addEventListener(
    "resize",
    () => {
      if (headerResizeRaf) return;
      headerResizeRaf = window.requestAnimationFrame(() => {
        headerResizeRaf = 0;
        syncHeaderMetrics();
        updateHeader();
      });
    },
    { passive: true }
  );
}

/* 2. Scroll Progress (Cached Max Scroll) ------------------------------ */
const progress = document.querySelector("[data-scroll-progress]");
if (progress) {
  const updateScrollProgress = () => {
    const y = window.scrollY;
    if (y <= 0) {
      progress.style.transform = "scaleX(0)";
      return;
    }
    const maxScroll = getMaxScroll();
    const ratio = maxScroll > 0 ? Math.min(1, Math.max(0, y / maxScroll)) : 0;
    progress.style.transform = `scaleX(${ratio})`;
  };
  registry.updateScrollProgress = updateScrollProgress;
  window.addEventListener("pageshow", (event) => {
    if (event.persisted && window.scrollY > 0) updateScrollProgress();
  }, { once: true });
  window.addEventListener("scroll", updateScrollProgress, { passive: true });
  window.addEventListener("resize", () => {
    refreshMaxScroll();
    updateScrollProgress();
  }, { passive: true });
}

/* 3. Copyright Year & Localized IST Time ------------------------------ */
const year = document.querySelector("[data-year]");
if (year) {
  year.textContent = String(new Date().getFullYear());
}

const localTime = document.querySelector("[data-local-time]");
if (localTime) {
  const formatter = new Intl.DateTimeFormat("en-IN", {
    timeZone: "Asia/Kolkata",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  });
  const updateLocalTime = () => {
    if (document.hidden) return;
    localTime.textContent = `${formatter.format(new Date())} IST`;
  };
  updateLocalTime();
  window.setInterval(updateLocalTime, 30000);
  document.addEventListener("visibilitychange", updateLocalTime);
}

/* 4. Intersection Reveal & Kicker Decode ------------------------------ */
const revealItems = Array.from(document.querySelectorAll("[data-reveal]"));
if (revealItems.length) {
  if (reduceMotion || !("IntersectionObserver" in window)) {
    revealItems.forEach((item) => item.classList.add("is-revealed"));
  } else {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add("is-revealed");
          observer.unobserve(entry.target);
        });
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.08 }
    );
    revealItems.forEach((item) => observer.observe(item));
  }
}

const decodeTargets = Array.from(document.querySelectorAll(".kicker"));
if (decodeTargets.length && !stillPlaying() && "IntersectionObserver" in window) {
  const decodeObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        if (entry.target.closest(".work-deck.is-deck-active .case:not(.is-front)")) return;
        entry.target.dataset.decoded = "true";
        decode(entry.target);
        decodeObserver.unobserve(entry.target);
      });
    },
    { threshold: 0.9 }
  );
  decodeTargets.forEach((el) => decodeObserver.observe(el));
}

/* 5. Case Stage Spotlight & Lightbox Dialog --------------------------- */
if (finePointer && !reduceMotion) {
  document.querySelectorAll("[data-stage]").forEach((stage) => {
    let frame = 0;
    stage.addEventListener("pointermove", (event) => {
      const card = stage.closest(".case");
      if (card && registry.workDeck && registry.workDeck.isActive() && !card.classList.contains("is-front")) {
        return;
      }
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        const rect = stage.getBoundingClientRect();
        const x = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
        const y = Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height));
        stage.style.setProperty("--mx", (x - 0.5).toFixed(3));
        stage.style.setProperty("--my", (y - 0.5).toFixed(3));
        stage.style.setProperty("--spot-x", `${(x * 100).toFixed(1)}%`);
        stage.style.setProperty("--spot-y", `${(y * 100).toFixed(1)}%`);
      });
    });

    stage.addEventListener("pointerleave", () => {
      window.cancelAnimationFrame(frame);
      stage.style.setProperty("--mx", "0");
      stage.style.setProperty("--my", "0");
      stage.style.setProperty("--spot-x", "74%");
      stage.style.setProperty("--spot-y", "18%");
    });
  });
}

const dialog = document.getElementById("screen-dialog");
if (dialog) {
  const slotA = dialog.querySelector("#screen-dialog-image");
  const slotB = dialog.querySelector("[data-screen-slot-alt]");
  const dialogCaption = dialog.querySelector("#screen-dialog-caption");
  const dialogTitle = dialog.querySelector("#screen-dialog-title");
  const dialogCounter = dialog.querySelector("#screen-dialog-counter");
  const tabsEl = dialog.querySelector("#screen-dialog-tabs");
  const viewport = dialog.querySelector("[data-screen-viewport]");
  const prevBtn = dialog.querySelector("[data-screen-prev]");
  const nextBtn = dialog.querySelector("[data-screen-next]");

  const EASE_OUT = "cubic-bezier(0.23, 1, 0.32, 1)";
  const imageCache = new Map();
  let lastTrigger = null;
  let screens = [];
  let activeIndex = 0;
  let displayedIndex = 0;
  let activeSlot = slotA;
  let switchToken = 0;
  let runningAnims = [];
  let loadingTimer = 0;

  const preloadImage = (src) => {
    if (!src) return Promise.resolve();
    if (imageCache.has(src)) return imageCache.get(src);
    const img = new Image();
    img.decoding = "async";
    img.src = src;
    const promise =
      typeof img.decode === "function"
        ? img.decode().catch(() => {})
        : new Promise((resolve) => {
            if (img.complete) return resolve();
            img.addEventListener("load", resolve, { once: true });
            img.addEventListener("error", resolve, { once: true });
          });
    imageCache.set(src, promise);
    return promise;
  };

  const cancelRunningAnims = () => {
    runningAnims.forEach((anim) => {
      try {
        anim.cancel();
      } catch {}
    });
    runningAnims = [];
    slotA?.classList.remove("is-exiting");
    slotB?.classList.remove("is-exiting");
    if (slotA) slotA.style.transform = "";
    if (slotB) slotB.style.transform = "";
  };

  const clearLoadingState = () => {
    window.clearTimeout(loadingTimer);
    loadingTimer = 0;
    viewport?.classList.remove("is-loading");
  };

  const formatCounter = (index, total) =>
    `${String(index + 1).padStart(2, "0")} / ${String(total).padStart(2, "0")}`;

  const syncControls = () => {
    if (dialogCounter) {
      dialogCounter.textContent = formatCounter(activeIndex, screens.length);
    }
    if (!tabsEl) return;
    tabsEl.querySelectorAll(".screen-dialog__tab").forEach((btn, idx) => {
      const selected = idx === activeIndex;
      btn.setAttribute("aria-pressed", String(selected));
      if (selected) {
        btn.scrollIntoView({
          block: "nearest",
          inline: "nearest",
          behavior: stillPlaying() ? "auto" : "smooth",
        });
      }
    });
  };

  const buildTabs = () => {
    if (!tabsEl) return;
    tabsEl.replaceChildren();
    if (screens.length <= 1) return;

    screens.forEach((item, idx) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "screen-dialog__tab";
      btn.setAttribute("aria-pressed", String(idx === activeIndex));

      const num = document.createElement("span");
      num.className = "screen-dialog__tab-num";
      num.textContent = String(idx + 1).padStart(2, "0");

      const label = document.createElement("span");
      label.className = "screen-dialog__tab-label";
      label.textContent = item.label;

      btn.append(num, label);
      btn.addEventListener("click", () => goToScreen(idx));
      tabsEl.appendChild(btn);
    });
  };

  const animateCaption = (textValue) => {
    if (!dialogCaption) return;
    dialogCaption.textContent = textValue;
    if (typeof dialogCaption.animate !== "function") return;
    const reduced = stillPlaying();
    const anim = dialogCaption.animate(
      reduced
        ? [{ opacity: 0 }, { opacity: 1 }]
        : [
            { opacity: 0, transform: "translate3d(0, 4px, 0)" },
            { opacity: 1, transform: "translate3d(0, 0, 0)" },
          ],
      { duration: reduced ? 120 : 200, easing: EASE_OUT }
    );
    runningAnims.push(anim);
  };

  const goToScreen = async (nextIndex, explicitDir = 0) => {
    if (!dialog.open || screens.length <= 1 || !slotA || !slotB) return;
    const total = screens.length;
    const targetIndex = ((nextIndex % total) + total) % total;

    if (targetIndex === activeIndex) return;
    if (targetIndex === displayedIndex) {
      ++switchToken;
      clearLoadingState();
      activeIndex = displayedIndex;
      syncControls();
      AudioFX.click();
      return;
    }

    const dir = explicitDir || (targetIndex > activeIndex ? 1 : -1);
    activeIndex = targetIndex;
    syncControls();
    AudioFX.click();

    const token = ++switchToken;
    const item = screens[targetIndex];

    clearLoadingState();
    loadingTimer = window.setTimeout(() => {
      if (token === switchToken && dialog.open) {
        viewport?.classList.add("is-loading");
      }
    }, 120);

    await preloadImage(item.src);
    if (token !== switchToken || !dialog.open) return;

    cancelRunningAnims();
    const candidate = activeSlot === slotA ? slotB : slotA;
    candidate.src = item.src;
    candidate.alt = item.alt;

    if (typeof candidate.decode === "function") {
      await candidate.decode().catch(() => {});
    }
    if (token !== switchToken || !dialog.open) return;

    clearLoadingState();

    const outgoing = activeSlot;
    const incoming = candidate;
    activeSlot = incoming;
    displayedIndex = targetIndex;

    outgoing.removeAttribute("id");
    outgoing.setAttribute("aria-hidden", "true");
    outgoing.classList.remove("is-active");
    outgoing.classList.add("is-exiting");

    incoming.id = "screen-dialog-image";
    incoming.setAttribute("aria-hidden", "false");
    incoming.classList.remove("is-exiting");
    incoming.classList.add("is-active");

    animateCaption(item.caption);

    const reduced = stillPlaying();
    if (typeof incoming.animate === "function" && typeof outgoing.animate === "function") {
      const outFrames = reduced
        ? [{ opacity: 1 }, { opacity: 0 }]
        : [
            { opacity: 1, transform: "translate3d(0, 0, 0) scale(1)", filter: "blur(0px)" },
            { opacity: 0, transform: `translate3d(${-dir * 34}px, 0, 0) scale(0.97)`, filter: "blur(4px)" },
          ];
      const inFrames = reduced
        ? [{ opacity: 0 }, { opacity: 1 }]
        : [
            { opacity: 0, transform: `translate3d(${dir * 34}px, 0, 0) scale(0.97)`, filter: "blur(4px)" },
            { opacity: 1, transform: "translate3d(0, 0, 0) scale(1)", filter: "blur(0px)" },
          ];

      const outAnim = outgoing.animate(outFrames, {
        duration: reduced ? 120 : 230,
        easing: EASE_OUT,
        fill: "forwards",
      });
      const inAnim = incoming.animate(inFrames, {
        duration: reduced ? 120 : 280,
        easing: EASE_OUT,
        fill: "forwards",
      });

      runningAnims.push(outAnim, inAnim);

      outAnim.onfinish = () => {
        outgoing.classList.remove("is-exiting");
        try {
          outAnim.cancel();
        } catch {}
      };
      inAnim.onfinish = () => {
        try {
          inAnim.cancel();
        } catch {}
      };
    } else {
      outgoing.classList.remove("is-exiting");
    }
  };

  const openScreen = (trigger) => {
    const stage = trigger.closest(".case-stage");
    const caseEl = trigger.closest(".case");
    hydrateMedia(stage || trigger);

    const source = trigger.dataset.full;
    if (!source || !slotA || !slotB || !dialogCaption) return;

    if (typeof dialog.showModal !== "function") {
      window.open(source, "_blank", "noopener");
      return;
    }

    const stageTriggers = stage ? Array.from(stage.querySelectorAll("[data-full]")) : [trigger];
    screens = stageTriggers
      .map((el, idx) => {
        const src = el.dataset.full;
        if (!src) return null;
        const imgEl = el.querySelector("img");
        const label =
          el.dataset.screenLabel ||
          el.closest(".phone")?.querySelector(".phone-label")?.textContent?.trim() ||
          el.closest(".browser-frame")?.querySelector(".browser-badge")?.textContent?.trim() ||
          `Screen ${idx + 1}`;
        return {
          trigger: el,
          src,
          alt: imgEl?.alt || el.dataset.caption || "Project screen",
          caption: el.dataset.caption || "",
          label,
        };
      })
      .filter(Boolean);

    if (!screens.length) return;

    lastTrigger = trigger;
    activeIndex = Math.max(
      0,
      screens.findIndex((item) => item.trigger === trigger)
    );
    displayedIndex = activeIndex;
    ++switchToken;
    cancelRunningAnims();
    clearLoadingState();

    if (stage) {
      const cs = window.getComputedStyle(stage);
      const accent = cs.getPropertyValue("--project-accent").trim();
      const glow = cs.getPropertyValue("--stage-glow").trim();
      if (accent) dialog.style.setProperty("--dialog-accent", accent);
      else dialog.style.removeProperty("--dialog-accent");
      if (glow) dialog.style.setProperty("--dialog-glow", glow);
      else dialog.style.removeProperty("--dialog-glow");
    } else {
      dialog.style.removeProperty("--dialog-accent");
      dialog.style.removeProperty("--dialog-glow");
    }

    const projectNum = stage?.querySelector(".stage-index")?.textContent?.trim();
    const projectName = caseEl?.querySelector("h3")?.textContent?.trim();
    if (dialogTitle) {
      dialogTitle.textContent =
        projectNum && projectName
          ? `${projectNum} · ${projectName}`
          : projectName || "Project screen";
    }

    dialog.dataset.multi = screens.length > 1 ? "true" : "false";
    buildTabs();
    syncControls();

    const current = screens[activeIndex];
    activeSlot = slotA;

    slotB.removeAttribute("id");
    slotB.setAttribute("aria-hidden", "true");
    slotB.classList.remove("is-active", "is-exiting");
    slotB.removeAttribute("src");
    slotB.alt = "";

    slotA.id = "screen-dialog-image";
    slotA.setAttribute("aria-hidden", "false");
    slotA.classList.remove("is-exiting");
    slotA.classList.add("is-active");
    slotA.src = current.src;
    slotA.alt = current.alt;
    dialogCaption.textContent = current.caption;

    screens.forEach((item) => preloadImage(item.src));

    if (!dialog.open) {
      dialog.showModal();
    }
    document.body.classList.add("dialog-open");
    dialog.focus({ preventScroll: true });
    AudioFX.click();
  };

  document.querySelectorAll("[data-full]").forEach((trigger) => {
    trigger.addEventListener("click", () => openScreen(trigger));
  });

  prevBtn?.addEventListener("click", () => goToScreen(activeIndex - 1, -1));
  nextBtn?.addEventListener("click", () => goToScreen(activeIndex + 1, 1));

  dialog.addEventListener("keydown", (event) => {
    if (!dialog.open || screens.length <= 1) return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      goToScreen(activeIndex - 1, -1);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      goToScreen(activeIndex + 1, 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      goToScreen(0, -1);
    } else if (event.key === "End") {
      event.preventDefault();
      goToScreen(screens.length - 1, 1);
    } else if (/^[1-9]$/.test(event.key)) {
      const idx = Number(event.key) - 1;
      if (idx < screens.length) {
        event.preventDefault();
        goToScreen(idx);
      }
    }
  });

  if (viewport) {
    let swipePointerId = null;
    let swipeStartX = 0;
    let swipeStartY = 0;
    let swipeLastX = 0;
    let swipeStartTime = 0;
    let swipeLocked = null;

    const resetSwipeTransform = (animateBack = false) => {
      if (!activeSlot) return;
      if (
        animateBack &&
        !stillPlaying() &&
        typeof activeSlot.animate === "function" &&
        activeSlot.style.transform
      ) {
        const fromTransform = activeSlot.style.transform;
        activeSlot.style.transform = "";
        activeSlot.animate(
          [{ transform: fromTransform }, { transform: "translate3d(0, 0, 0)" }],
          { duration: 180, easing: EASE_OUT }
        );
      } else {
        activeSlot.style.transform = "";
      }
    };

    viewport.addEventListener("pointerdown", (event) => {
      if (event.pointerType !== "touch" || screens.length <= 1 || !dialog.open) return;
      if (swipePointerId !== null) return;
      swipePointerId = event.pointerId;
      swipeStartX = event.clientX;
      swipeStartY = event.clientY;
      swipeLastX = event.clientX;
      swipeStartTime = performance.now();
      swipeLocked = null;
    });

    viewport.addEventListener("pointermove", (event) => {
      if (event.pointerId !== swipePointerId) return;
      const dx = event.clientX - swipeStartX;
      const dy = event.clientY - swipeStartY;
      if (swipeLocked === null && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
        swipeLocked = Math.abs(dx) > Math.abs(dy) * 1.15 ? "x" : "y";
        if (swipeLocked === "x" && typeof viewport.setPointerCapture === "function") {
          try {
            viewport.setPointerCapture(event.pointerId);
          } catch {}
        }
      }
      if (swipeLocked !== "x") return;
      swipeLastX = event.clientX;
      if (!stillPlaying() && activeSlot) {
        const damped = Math.max(-72, Math.min(72, dx * 0.35));
        activeSlot.style.transform = `translate3d(${damped.toFixed(1)}px, 0, 0)`;
      }
    });

    const endSwipe = (event) => {
      if (event.pointerId !== swipePointerId) return;
      const wasHorizontal = swipeLocked === "x";
      const dx = (wasHorizontal ? event.clientX : swipeLastX) - swipeStartX;
      const dt = Math.max(1, performance.now() - swipeStartTime);
      const velocity = Math.abs(dx) / dt;
      swipePointerId = null;
      swipeLocked = null;

      if (wasHorizontal && (Math.abs(dx) >= 42 || velocity > 0.25)) {
        const step = dx < 0 ? 1 : -1;
        resetSwipeTransform(false);
        goToScreen(activeIndex + step, step);
      } else {
        resetSwipeTransform(wasHorizontal);
      }
    };

    viewport.addEventListener("pointerup", endSwipe);
    viewport.addEventListener("pointercancel", (event) => {
      if (event.pointerId !== swipePointerId) return;
      swipePointerId = null;
      swipeLocked = null;
      resetSwipeTransform(true);
    });
  }

  dialog.addEventListener("close", () => {
    if (dialog.open) return;
    ++switchToken;
    cancelRunningAnims();
    clearLoadingState();
    document.body.classList.remove("dialog-open");
    screens = [];
    tabsEl?.replaceChildren();
    [slotA, slotB].forEach((slot) => {
      if (!slot) return;
      slot.classList.remove("is-active", "is-exiting");
      slot.removeAttribute("src");
      slot.alt = "";
    });
    if (slotA) {
      slotA.id = "screen-dialog-image";
      slotA.setAttribute("aria-hidden", "false");
    }
    if (slotB) {
      slotB.removeAttribute("id");
      slotB.setAttribute("aria-hidden", "true");
    }
    activeSlot = slotA;
    if (lastTrigger) {
      lastTrigger.focus({ preventScroll: true });
      lastTrigger = null;
    }
  });

  dialog.addEventListener("click", (event) => {
    if (event.target === dialog) dialog.close();
  });
}

