const observeLoad = (selector, loaderFn, rootMargin = "550px 0px") => {
  const el = document.querySelector(selector);
  if (!el) return;
  if (!("IntersectionObserver" in window)) {
    loaderFn();
    return;
  }
  const io = new IntersectionObserver(
    (entries) => {
      if (entries.some((e) => e.isIntersecting)) {
        io.disconnect();
        loaderFn();
      }
    },
    { rootMargin }
  );
  io.observe(el);
};

