/* Global Keyboard OS */
window.addEventListener("keydown", (e) => {
  if (document.documentElement.classList.contains("is-preloading")) {
    return;
  }
  const tag = document.activeElement ? document.activeElement.tagName.toLowerCase() : "";
  const isInput = tag === "input" || tag === "textarea" || Boolean(document.activeElement?.isContentEditable);

  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
    if (!registry.paletteAPI) {
      e.preventDefault();
      e.stopImmediatePropagation();
      const activeEl = document.activeElement;
      registry.loaders.palette().then((api) => {
        const pal = document.getElementById("palette");
        if (pal && !pal.open) api?.openPalette(activeEl);
      });
    }
    return;
  }

  if (isInput) return;
  if (document.querySelector("dialog[open]")) return;

  const key = e.key.toLowerCase();
  const projectMap = {
    1: "#project-shoboti",
    2: "#project-hisab",
    3: "#project-simvox",
    4: "#project-mrproper",
    5: "#project-tenderiq",
  };

  if (projectMap[key] && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    navigateToHash(projectMap[key]);
    AudioFX.click();
    return;
  }

  if (key === "c" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    const email = "agrawalmayank1111@gmail.com";
    if (navigator.clipboard) {
      navigator.clipboard
        .writeText(email)
        .then(() => Toast.show(`Copied ${email} to clipboard!`, "success"))
        .catch(() => Toast.show(`Email: ${email}`, "info"));
    } else {
      Toast.show(`Email: ${email}`, "info");
    }
    return;
  }

  if (key === "r" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    AudioFX.chime();
    Toast.show("Opening Mayank Agrawal's Resume (PDF)...", "info");
    window.open("Mayank_Agrawal_Resume.pdf", "_blank", "noopener");
    return;
  }

  if (key === "s" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    AudioFX.init();
    AudioFX.setEnabled(!AudioFX.isEnabled());
    Toast.show(`Tactile Sound: ${AudioFX.isEnabled() ? "ENABLED (Web Audio API)" : "MUTED"}`, "info");
  }
});

/* 9. Background Hydration & Preloader Curtain (1 -> 100) ---------------- */
const runWhenIdle = (fn, timeout = 1200) => {
  if (typeof window.requestIdleCallback === "function") {
    window.requestIdleCallback(fn, { timeout });
  } else {
    window.setTimeout(fn, Math.min(600, timeout));
  }
};

const bootHeroMesh = () =>
  document.querySelector(".hero-mesh") && registry.loaders.heroMesh
    ? registry.loaders.heroMesh().catch(() => {})
    : Promise.resolve();

const mascotHost = document.querySelector("[data-mascot]");
let mascotBootPromise = null;

const bootMascot = () => {
  if (mascotBootPromise) return mascotBootPromise;
  if (!mascotHost) {
    mascotBootPromise = Promise.resolve();
    return mascotBootPromise;
  }

  mascotBootPromise = new Promise((resolve) => {
    let settled = false;
    let observer = null;
    const finish = () => {
      if (settled) return;
      settled = true;
      if (observer) observer.disconnect();
      resolve();
    };

    if (
      mascotHost.classList.contains("is-webgl-ready") ||
      mascotHost.classList.contains("mascot--failed")
    ) {
      finish();
      return;
    }

    if ("MutationObserver" in window) {
      observer = new MutationObserver(() => {
        if (
          mascotHost.classList.contains("is-webgl-ready") ||
          mascotHost.classList.contains("mascot--failed")
        ) {
          finish();
        }
      });
      observer.observe(mascotHost, { attributes: true, attributeFilter: ["class"] });
    }

    registry.loaders.mascotSpeech?.().catch(() => {});

    import("../mascot3d.js")
      .then(() => {
        registry.mascotGlance = (x, y) => {
          if (typeof window.__mascotGlance === "function") {
            window.__mascotGlance(x, y);
          }
        };
        registry.mascotSection = (id) => {
          if (typeof window.__mascotSection === "function") {
            window.__mascotSection(id);
          }
        };
        registry.mascotCheer = (kind) => {
          if (typeof window.__mascotCheer === "function") {
            window.__mascotCheer(kind);
          }
        };
        if (
          mascotHost.classList.contains("is-webgl-ready") ||
          mascotHost.classList.contains("mascot--failed") ||
          !observer
        ) {
          finish();
        }
      })
      .catch((error) => {
        mascotHost.classList.add("mascot--failed");
        console.warn("mascot: unavailable", error);
        finish();
      });

    window.setTimeout(finish, 2400);
  });

  return mascotBootPromise;
};

const nextFrame = () => new Promise((resolve) => window.requestAnimationFrame(resolve));

const warmPageElements = async () => {
  const batches = [
    [registry.loaders.workDeck, registry.loaders.workbenches],
    [registry.loaders.aboutToolkit, registry.loaders.expTheater],
    [registry.loaders.colophon, registry.loaders.consoleShell],
    [registry.loaders.contact, registry.loaders.palette],
  ];

  for (const batch of batches) {
    await nextFrame();
    await Promise.all(
      batch.filter(Boolean).map((loader) => loader().catch(() => {}))
    );
  }

  await nextFrame();
  const workEl = document.getElementById("work");
  if (workEl) hydrateMedia(workEl);
  const aboutEl = document.getElementById("about");
  if (aboutEl) hydrateMedia(aboutEl);
};

const preloader = document.getElementById("preloader");
if (!preloader || stillPlaying()) {
  document.documentElement.classList.remove("is-preloading");
  if (preloader) preloader.remove();
  resolvePreloaderDone();
  bootHeroMesh();
  bootMascot();
  runWhenIdle(warmPageElements, 1200);
} else {
  const counterEl = preloader.querySelector("[data-preloader-counter]");
  const fillEl = preloader.querySelector("[data-preloader-fill]");
  const landmarks = Array.from(
    document.querySelectorAll(
      "header.site-header, main, footer.site-footer, aside.hud, .colophon-drawer, .menu-toggle"
    )
  ).filter((el) => !el.hasAttribute("inert"));

  document.documentElement.classList.add("is-preloading");
  landmarks.forEach((el) => el.setAttribute("inert", ""));

  const MIN_MS = 1450;
  const MAX_WAIT_MS = 2800;
  const easeInOutQuad = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

  let loadedWeight = 0;
  let completedTasks = 0;
  let allTasksDone = false;

  const pageLoadPromise =
    document.readyState === "complete"
      ? Promise.resolve()
      : new Promise((resolve) => window.addEventListener("load", resolve, { once: true }));

  const fontsPromise =
    document.fonts && document.fonts.ready ? document.fonts.ready.catch(() => {}) : Promise.resolve();

  const sectionsPromise = new Promise((resolve) => {
    window.requestAnimationFrame(() => {
      warmPageElements().then(resolve, resolve);
    });
  });

  const bgTasks = [
    { promise: fontsPromise, weight: 0.15 },
    { promise: pageLoadPromise, weight: 0.15 },
    { promise: bootHeroMesh(), weight: 0.15 },
    { promise: bootMascot(), weight: 0.35 },
    { promise: sectionsPromise, weight: 0.2 },
  ];

  bgTasks.forEach(({ promise, weight }) => {
    Promise.resolve(promise)
      .catch(() => {})
      .finally(() => {
        loadedWeight = Math.min(1, loadedWeight + weight);
        completedTasks += 1;
        if (completedTasks >= bgTasks.length) {
          allTasksDone = true;
        }
      });
  });

  let rafId = 0;
  let finished = false;
  let startedAt = 0;
  let lastFrameAt = 0;
  let displayP = 0;
  let lastShown = 1;
  let brandShown = false;

  const releaseLandmarks = () => {
    document.documentElement.classList.remove("is-preloading");
    landmarks.forEach((el) => el.removeAttribute("inert"));
  };

  const cleanup = () => {
    if (!preloader.isConnected) return;
    releaseLandmarks();
    preloader.remove();
  };

  const startExit = () => {
    if (finished) return;
    finished = true;
    window.cancelAnimationFrame(rafId);

    if (counterEl && lastShown !== 100) {
      counterEl.textContent = "100";
      lastShown = 100;
    }
    if (fillEl) {
      fillEl.style.transform = "scaleX(1)";
    }
    preloader.classList.add("is-ready", "is-complete");

    window.setTimeout(() => {
      preloader.classList.add("is-exiting");
      window.setTimeout(() => {
        releaseLandmarks();
        resolvePreloaderDone();
        preloader.classList.add("is-leaving");
        preloader.addEventListener(
          "transitionend",
          (event) => {
            if (event.target === preloader && event.propertyName === "transform") {
              cleanup();
            }
          },
          { once: true }
        );
        window.setTimeout(cleanup, 750);
      }, 150);
    }, 110);
  };

  const step = (now) => {
    if (finished) return;
    if (!startedAt) {
      startedAt = now;
      lastFrameAt = now;
    }
    const elapsed = now - startedAt;
    const dt = Math.min(0.08, Math.max(0.008, (now - lastFrameAt) / 1000));
    lastFrameAt = now;

    if (!brandShown && elapsed >= 180) {
      brandShown = true;
      preloader.classList.add("is-ready");
    }

    if (elapsed >= MAX_WAIT_MS) {
      allTasksDone = true;
    }

    const timeNorm = Math.min(1, elapsed / MIN_MS);
    const timeEased = easeInOutQuad(timeNorm);
    const desiredP = allTasksDone
      ? timeEased
      : Math.min(0.92, timeEased * 0.58 + loadedWeight * 0.38);

    const follow = 1 - Math.exp(-(allTasksDone ? 12 : 8.5) * dt);
    displayP = Math.max(displayP, displayP + (desiredP - displayP) * follow);

    if (allTasksDone && timeNorm >= 1 && displayP >= 0.992) {
      displayP = 1;
    }

    const value = Math.min(100, Math.max(1, 1 + Math.round(displayP * 99)));
    if (value !== lastShown && counterEl) {
      lastShown = value;
      counterEl.textContent = String(value);
    }
    if (fillEl) {
      fillEl.style.transform = `scaleX(${(0.01 + displayP * 0.99).toFixed(4)})`;
    }

    if (displayP < 1) {
      rafId = window.requestAnimationFrame(step);
    } else {
      startExit();
    }
  };

  const onKeySkip = (event) => {
    if (event.key === "Escape" && !finished) {
      window.removeEventListener("keydown", onKeySkip);
      startExit();
    }
  };
  window.addEventListener("keydown", onKeySkip);
  window.setTimeout(() => {
    window.removeEventListener("keydown", onKeySkip);
    startExit();
  }, MAX_WAIT_MS + 700);

  rafId = window.requestAnimationFrame(step);
}
